/// <summary>
/// Transfer order shipment bundling report class.
/// </summary>
[SrsReportParameterAttribute(classStr(METOrderShipmentBundlingReportContract)),
 SRSReportQueryAttribute(queryStr(METOrderShipmentBundlingReportingJobQuery))]
public class METTransferOrderShipmentBundlingReportDP extends SrsReportDataProviderPreProcessTempDB
{
    METOrderShipmentBundlingReportContract      contract;
    METOrderShipmentBundlingReportHeaderTmp     bundleHeaderTmp;
    METCoverNoteContract                        coverNoteContract;
    METCommonReportContract                     commonReportContract;
    METCommonContinuingPermissionNoticeContract commonContinuingPermissionNoticeContract; 
    METTransferOrderShippmentContract           transferShipmentContract;
    METCoverNoteDP                      coverNoteDP;
    METDangerousGoodsManifestDP         dangerousGoodsManifestDP;
    METTOContinuingPermissionNoticeDP   continuingPermissionNoticeDP;
    METMultimodalDangerousGoodsDP       multimodalDangerousGoodsDP;
    METTransferOrderShippmentDP         transferOrderShipmentDP;
    MetShipmentId   shipmentId;
    MetLoadId       loadId;
    boolean         isReprint;

    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerTableGuid;


}

Method.Source:
/// <summary>
/// New method to initialize all DP classes.
/// </summary>
public void new()
{
    coverNoteDP = new METCoverNoteDP();
    dangerousGoodsManifestDP = new METDangerousGoodsManifestDP();
    continuingPermissionNoticeDP = new METTOContinuingPermissionNoticeDP();
    multimodalDangerousGoodsDP = new METMultimodalDangerousGoodsDP();
    transferOrderShipmentDP = new METTransferOrderShippmentDP();
    super();
}

/// <summary>
/// ProcessReport
/// </summary>
public void processReport()
{
    METSalesOrderShipmentLoadHeader     shipmentLoadHeader, shipmentLoadHeaderCount;
    METSalesOrderShipmentLoadLines      shipmentLoadLines;
    Str1260                             listOfShipmentsInLoad;
    METProcMetrics                      procMetrics = METProcMetricsScope::current();

    bundleHeaderReportGuid = guid2Str(newGuid()); 
    contract = this.parmDataContract();

    shipmentId  = contract.parmShipmentId();
    loadId      = contract.parmLoadId();
    isReprint     = contract.parmIsReprint();

    try
    {
        if (!isReprint)
        {
            select count(RecId) from shipmentLoadHeaderCount
                where shipmentLoadHeaderCount.LoadId == loadId;
        }

        while select ShipmentId from shipmentLoadHeader
            group by ShipmentId
            where shipmentLoadHeader.LoadId == loadId
        {
            if (listOfShipmentsInLoad)
            {
                listOfShipmentsInLoad += ', ';
            }
            listOfShipmentsInLoad += shipmentLoadHeader.ShipmentId;
        }

        select firstonly shipmentLoadHeader
            where shipmentLoadHeader.ShipmentId == shipmentId   &&
                shipmentLoadHeader.LoadId == loadId;

        bundleHeaderTmp.LoadID = loadId;
        bundleHeaderTmp.ShipmentID = shipmentId;
        bundleHeaderTmp.Route = shipmentLoadHeader.Route;
        bundleHeaderTmp.RouteStopNum = shipmentLoadHeader.RouteStopNum;
        bundleHeaderTmp.ListOfShipmentsInLoad = listOfShipmentsInLoad;
        bundleHeaderTmp.Warehouse = shipmentLoadHeader.Warehouse;

        if (isReprint)
        {
            bundleHeaderTmp.TotalNumOfShipment = 1;
        }
        else
        {
            bundleHeaderTmp.TotalNumOfShipment = shipmentLoadHeaderCount.RecId;
        }
        bundleHeaderTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
        bundleHeaderTmp.insert();

        //***** Shipment based report ***//
        if (procMetrics)
        {
            select count(RecId) from shipmentLoadLines 
                where shipmentLoadLines.ShipmentId == shipmentId;

            procMetrics.incLineCount(shipmentLoadLines.RecId);
            procMetrics.startDescriptionTime(2, "@MET:CoverNote");
        }

        //CoverNote
        coverNoteContract = new METCoverNoteContract();
        headerTableGuid = guid2Str(newGuid());
        coverNoteContract.parmShipmentId(shipmentLoadHeader.ShipmentId);
        coverNoteDP.parmDataContract(coverNoteContract);
        coverNoteDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
        coverNoteDP.processReport();

        if (procMetrics)
        {
            procMetrics.incDescriptionCount(2);
            procMetrics.endDescriptionTime(2);
            procMetrics.startDescriptionTime(3, "@MET:METDangerousGoodsReport");
        }

        commonReportContract = new METCommonReportContract();
        headerTableGuid = guid2Str(newGuid());
        commonReportContract.parmRecId(shipmentLoadHeader.RecId);
        dangerousGoodsManifestDP.parmDataContract(commonReportContract);
        dangerousGoodsManifestDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
        dangerousGoodsManifestDP.processReport();

        if (procMetrics)
        {
            procMetrics.incDescriptionCount(3);
            procMetrics.endDescriptionTime(3);
            procMetrics.startDescriptionTime(4, "@MET:SODMultimodalDG");
        }

        commonReportContract = new METCommonReportContract();
        headerTableGuid = guid2Str(newGuid()) ; 
        commonReportContract.parmRecId(shipmentLoadHeader.RecId);
        multimodalDangerousGoodsDP.parmDataContract(commonReportContract);
        multimodalDangerousGoodsDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
        multimodalDangerousGoodsDP.processReport();

        if (procMetrics)
        {
            procMetrics.incDescriptionCount(4);
            procMetrics.endDescriptionTime(4);
            procMetrics.setDescription(5, "@MET:METContinuingPermissionNotice");
            procMetrics.setDescription(6, "@MET:TransferOrderShipment");
        }

        while select shipmentLoadLines
            group by OrderNum
            where shipmentLoadLines.ShipmentId == shipmentId
        {
            commonContinuingPermissionNoticeContract = new METCommonContinuingPermissionNoticeContract();
            headerTableGuid = guid2Str(newGuid());
            commonContinuingPermissionNoticeContract.parmSalesId(shipmentLoadLines.OrderNum);

            if (procMetrics)
            {
                procMetrics.startDescriptionTime(5);
            }
            continuingPermissionNoticeDP.parmDataContract(commonContinuingPermissionNoticeContract);
            continuingPermissionNoticeDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
            continuingPermissionNoticeDP.processReport();

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(5);
                procMetrics.endDescriptionTime(5);
                procMetrics.startDescriptionTime(6);
            }

            transferShipmentContract = new METTransferOrderShippmentContract();
            headerTableGuid = guid2Str(newGuid());
            transferShipmentContract.parmTransferId(shipmentLoadLines.OrderNum);

            transferOrderShipmentDP.parmDataContract(transferShipmentContract);
            transferOrderShipmentDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
            transferOrderShipmentDP.processReport();

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(6);
                procMetrics.endDescriptionTime(6);
            }
        }
    }
    catch
    {
        throw Error(strFmt("@MET:BundlingError", shipmentId));
    }

}

